contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(bool trySetApprove, address _keep) public payable {
        // record approval status before any actions (view call allowed anywhere)
        bool beforeApproved = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        // If requested, attempt to set approved logger status using a top-level state-changing call
        // This may revert; capture via try/catch at top level as required.
        bool setApproveReverted;
        c.setApprovedLogger(address(this), true); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setApproveReverted = true;
        } else {
            setApproveReverted = false;
        }

        // Read approval status after attempted change
        bool afterApproved = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        // Now call the mutating log function logCreated as a top-level call and capture its return / revert
        bool returned;
        bool didRevert;
        bool r = c.logCreated(_keep); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            returned = false;
            didRevert = true;
        } else {
            returned = r;
            didRevert = false;
        }

        // General property: logCreated must not revert; its boolean return equals the approval status at call time.
        // Expressed without referencing private state: returned == afterApproved and didRevert == false
        assert(didRevert == false && returned == afterApproved);
    }

    receive() external payable {}
}

