// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(bool trySetApprove, address _keep) internal {
        bool beforeApproved;
        try c.approvedToLog(address(this)) returns (bool __r) { beforeApproved = __r; } catch { return; }
        bool setApproveReverted;
        try c.setApprovedLogger(address(this), true) {
            setApproveReverted = false;
        } catch {
            setApproveReverted = true;
        }
        bool afterApproved;
        try c.approvedToLog(address(this)) returns (bool __r) { afterApproved = __r; } catch { return; }
        bool returned;
        bool didRevert;
        try c.logCreated(_keep) returns (bool r) {
            returned = r;
            didRevert = false;
        } catch {
            returned = false;
            didRevert = true;
        }
        assertTrue(didRevert == false && returned == afterApproved);
    }

    function testFuzz_run(bool trySetApprove, address _keep) public {
        vm.assume(_keep.code.length == 0 && uint160(_keep) > 0xffff && _keep != address(this) && _keep != address(c) && _keep != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _keep != 0x000000000000000000636F6e736F6c652e6c6f67 && _keep != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _keep != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(trySetApprove, _keep);
    }

    receive() external payable {}
}
